```js
// Resolve all brick collisions for one frame: kills, score/combo, and a real
// per-face bounce. Repeatedly re-scans because a bounce can push the ball into
// a neighbouring brick (rows/columns touch corner-to-corner via the gaps).
export function resolveBricks(state) {
  let guard = state.bricks.length;
  while (guard-- > 0) {
    let hit = false;
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (!collides(state.ball, brick)) continue;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      bounceOffBrick(state.ball, brick);
      hit = true;
      break; // re-scan: the bounce may have moved the ball into another brick
    }
    if (!hit) break;
  }
}
```

