```js
// Bounces the ball off the face of `brick` it actually hit and pushes it out
// of the brick. Face choice = the axis with the shallowest penetration (that's
// the face the ball is crossing); the push-out direction follows the ball's
// incoming direction so it exits the way it came, never deeper inside.
export function bounceOffBrick(ball, brick) {
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

  if (overlapX < overlapY) {
    // Side hit: mirror the horizontal velocity.
    if (ball.vx > 0) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
    ball.vx = -ball.vx;
  } else {
    // Top/bottom hit: mirror the vertical velocity.
    if (ball.vy > 0) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
    ball.vy = -ball.vy;
  }
}
```

