// --- Rendering (DOM): brick collisions resolved before the draw pass --------

// Main render loop. Brick resolution (kills, score, bounce) runs first as pure
// logic; the draw pass only renders what is still alive.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Brick collisions + scoring: pure logic, kept out of the draw pass (#1).
  resolveBricks(state);

  // Bricks: drawing only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

