// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Issue #1: brick bounces -------------------------------------------------

// Park the ball at a given position/velocity, remembering where it came from
// this frame (exactly what step() records via ball.prevX / ball.prevY).
function aim(state, x, y, vx, vy, fromX, fromY) {
  state.ball.x = x;
  state.ball.y = y;
  state.ball.vx = vx;
  state.ball.vy = vy;
  state.ball.prevX = fromX ?? x;
  state.ball.prevY = fromY ?? y;
  return state.ball;
}

test('#1 per-face: smaller X penetration is a side hit — flips vx, leaves vy', () => {
  const brick = { x: 200, y: 100, w: 72, h: 20 };
  const ball = { x: 205, y: 110, r: 7, vx: 300, vy: 0 }; // 12 px into the left face
  const face = bounceOffBrick(ball, brick);
  assert.equal(face, 'left');
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, 0, 'the other component must stay untouched');
  assert.equal(ball.x, brick.x - ball.r, 'ball pushed out of the left face');
  assert.equal(ball.y, 110);
  assert.equal(collides(ball, brick), false, 'push-out clears the brick');
});

test('#1 per-face: smaller Y penetration is a top hit — flips vy, leaves vx', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20 };
  const ball = { x: 136, y: 112, r: 7, vx: 100, vy: 300 }; // falling onto the top face
  const face = bounceOffBrick(ball, brick);
  assert.equal(face, 'top');
  assert.equal(ball.vy, -300);
  assert.equal(ball.vx, 100, 'the other component must stay untouched');
  assert.equal(ball.y, brick.y - ball.r, 'ball pushed out of the top face');
  assert.equal(ball.x, 136);
  assert.equal(collides(ball, brick), false, 'push-out clears the brick');
});

test('#1 corner: equal penetration is a diagonal hit — flips both components', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20 };
  const ball = { x: 106, y: 106, r: 7, vx: -300, vy: 300 }; // 13 px into each face
  const face = bounceOffBrick(ball, brick);
  assert.equal(face, 'corner');
  assert.equal(ball.vx, 300);
  assert.equal(ball.vy, -300);
  assert.equal(collides(ball, brick), false, 'push-out clears the brick');
});

test('#1 push-out: a bounce never leaves the ball inside the brick', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20 };
  const ball = { x: 136, y: 126, r: 7, vx: 0, vy: -300 }; // below the brick, moving up
  bounceOffBrick(ball, brick);
  assert.equal(collides(ball, brick), false);
  assert.equal(ball.y, brick.y + brick.h + ball.r, 'parked tangent below the brick');
  assert.equal(ball.vy, 300);
});

test('#1 head-on: ball plowing into a column bounces back and scores', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === BRICK_ROWS - 1);
  const ball = aim(
    state,
    brick.x + brick.w / 2,
    brick.y + brick.h + ball.r - 1, // 1 px into the bottom face
    0, -260,
    brick.x + brick.w / 2, 190,
  );
  resolveBricks(state);
  assert.equal(brick.alive, false);
  assert.equal(state.combo, 1);
  assert.equal(state.score, scoreForBrick(brick, 1));
  assert.equal(ball.vy, 260, 'bounced back down, not straight through');
  assert.equal(ball.y, brick.y + brick.h + ball.r, 'pushed back below the brick');
});

test('#1 neighbours: seam overlap bounces exactly once (no double-flip cancel)', () => {
  const state = createState(1);
  const upper = state.bricks.find((b) => b.row === 3);
  const lower = state.bricks.find((b) => b.row === 4 && b.x === upper.x);
  // Ball moving up-right across the 8 px gap between the two rows: it overlaps
  // both bricks in the same pass (gap 8 < ball 14). Bouncing once per brick
  // would flip vy twice and cancel out.
  const ball = aim(
    state,
    upper.x + 4, 128,
    300, -260,
    upper.x - 14, 124,
  );
  resolveBricks(state);
  assert.equal(upper.alive, false);
  assert.equal(lower.alive, false);
  assert.equal(state.combo, 2);
  assert.equal(state.score, scoreForBrick(upper, 1) + scoreForBrick(lower, 2));
  assert.equal(ball.vy, 260, 'vy flipped exactly once');
  assert.equal(ball.vx, 300, 'horizontal component left untouched');
});

test('#1 tunnelling: a level-6 ball cannot jump over a brick (swept detection)', () => {
  const state = createState(6); // ballSpeed(6) = 710 px/s
  const brick = state.bricks.find((b) => b.row === BRICK_ROWS - 1);
  const r = state.ball.r;
  // One stuttered frame at the 50 ms cap: 710 * 0.05 = 35.5 px. The ball jumps
  // from below the brick (188.4) to above it (152.9) — 35.5 px across a 34 px
  // crossing window — without ever overlapping it discretely.
  const ball = aim(
    state,
    brick.x + brick.w / 2, 152.9,
    0, -710,
    brick.x + brick.w / 2, 188.4,
  );
  assert.equal(collides(ball, brick), false, 'the discrete test alone would miss it');
  resolveBricks(state);
  assert.equal(brick.alive, false);
  assert.equal(state.combo, 1);
  assert.equal(state.score, scoreForBrick(brick, 1));
  assert.equal(ball.vy, 710, 'bounced back down instead of passing through');
  assert.equal(ball.y, brick.y + brick.h + r, 'ball parked below the brick');
});

test('#1: resolveBricks is a no-op when the ball is nowhere near the bricks', () => {
  const state = createState(1);
  const score = state.score;
  aim(state, WIDTH / 2, 400, 100, 200, WIDTH / 2 - 2, 398);
  resolveBricks(state);
  assert.ok(state.bricks.every((b) => b.alive));
  assert.equal(state.score, score);
  assert.equal(state.combo, 0);
});

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

