  // than the 34 px it takes to cross the brick (BRICK_H + diameter). The ball
  // goes from y = 127.5 (below, not touching) to y = 92 (above, not touching)
  // — the discrete test alone never sees the brick.
  const state = {
    combo: 0,
    score: 0,
    ball: { x: 136, y: 92, r: 7, vx: 0, vy: -710, prevX: 136, prevY: 127.5 },
    bricks: [brick],
