node --input-type=module -e "
import { createState, step, resolveBricks, collides } from './game/neon.js';

// Simulate: ball flying up into the bottom row, head-on.
const state = createState(1);
const dt = 1/60;
const hitBricks = [];
for (let f = 0; f < 200 && state.bricks.some(b => b.alive); f++) {
  step(state, dt);
  const before = state.bricks.filter(b => !b.alive).length;
  resolveBricks(state);
  const after = state.bricks.filter(b => !b.alive).length;
  if (after > before) hitBricks.push(f);
  // ball must never be stuck inside a live brick
  const stuck = state.bricks.some(b => b.alive && collides(state.ball, b));
  if (stuck) { console.log('STUCK at frame', f); break; }
  if (state.ball.y > 480) { console.log('ball lost at frame', f); break; }
}
const live = state.bricks.filter(b => b.alive).length;
console.log('bricks broken in frames:', hitBricks.slice(0,10).join(','), '...');
console.log('surviving bricks:', live, '| score:', state.score, '| combo:', state.combo);
console.log('ball pos:', state.ball.x.toFixed(1), state.ball.y.toFixed(1), 'vel:', state.ball.vx.toFixed(1), state.ball.vy.toFixed(1));
"

